8	/**
9	 * Resolves whether the owner response should carry a per-city capacity warning and publishes it for
10	 * the responder. The warning is raised once the owner's city holds at least {@value #WARN_THRESHOLD}
11	 * owners but is still below {@link EnsureCityCapacity#CAPACITY}, i.e. it is approaching (but has not
12	 * reached) the hard limit that {@link EnsureCityCapacity} enforces. Runs before the responder so both
13	 * the create and read responses carry the flag.
14	 */
15	public class ResolveCapacityWarning {
16	
17	    /** A city warns once it holds this many owners, approaching {@link EnsureCityCapacity#CAPACITY}. */
18	    static final int WARN_THRESHOLD = 40;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository,
21	            @CapacityWarning Out<Boolean> capacityWarning) {
22	        long count = ownerRepository.countByCity(owner.getCity());
23	        capacityWarning.set(count >= WARN_THRESHOLD && count < EnsureCityCapacity.CAPACITY);
24	    }
25	}
